insert into public.incidents (id, round_id, session_id, reporter_driver_id, reporter_contact, involved_driver_ids, lap, corner, description, clip_url, clip_timestamp, submitted_at, ip_hash, source, status) values
  (1, 10, 21, 9, 'gravel_gustav', '{9,10}'::bigint[], 3, 'Kurve 1', 'Beim Anbremsen auf Kurve 1 wurde ich von hinten getroffen und habe mich gedreht.', 'https://youtu.be/beispiel?t=754', '12:34', '2026-09-15T14:00:00.000Z', NULL, 'report', 'decided'),
  (2, 11, 24, 14, 'eaurouge_emil', '{14,13}'::bigint[], 8, 'Kurve 10', 'Ich wurde beim Überholversuch von der Strecke gedrängt.', 'https://medal.tv/games/f1/clips/beispiel', '0:42', '2026-09-23T00:00:00.000Z', NULL, 'report', 'decided'),
  (3, 12, 26, 5, 'drs_dani', '{5,11}'::bigint[], 1, 'Kurve 11', 'Kontakt beim Einlenken, ich musste in die Auslaufzone.', 'https://www.twitch.tv/videos/123456789', '1:02:10', '2026-09-29T00:00:00.000Z', 'demo', 'report', 'new'),
  (4, 12, 26, 19, 'maxattackmia', '{19,22}'::bigint[], 14, 'Kurve 17', 'Unsicheres Wiedereinfahren nach Dreher direkt vor mir.', 'https://streamable.com/beispiel', NULL, '2026-09-29T03:00:00.000Z', 'demo', 'report', 'in_review')
insert into public.decisions (id, public_ref, incident_id, round_id, session_id, driver_id, verdict, time_seconds, positions, penalty_points, reasoning_de, reasoning_en, rule_ref, clip_url, decided_by, status, published_at) values
  (1, 'S1-R06-01', NULL, 6, 13, 6, 'dsq', NULL, NULL, NULL, 'Nach Auswertung des Replays wurde festgestellt, dass mit einer laut Lobby-Einstellungen nicht erlaubten Fahrhilfe gefahren wurde. Die Disqualifikation wurde nach der Final-Setzung ausgesprochen, das Ergebnis wurde korrigiert.', 'The replay showed that an assist not permitted by the lobby settings was used. The disqualification was issued after the result had been finalised; the result has been corrected.', '§10', NULL, '{}'::uuid[], 'published', '2026-04-17T22:00:00.000Z'),
  (2, 'S2-R02-01', 1, 10, 21, 10, 'time_penalty', 5, NULL, NULL, 'Oversteer_Olli hat den Bremspunkt verpasst und GravelTrap_Gustav in Kurve 1 von hinten getroffen. Gustav drehte sich und verlor mehrere Positionen. Hauptschuld bei Car #10 (Strafenkatalog V-02).', 'Oversteer_Olli missed his braking point and hit GravelTrap_Gustav from behind at turn 1. Gustav spun and lost several positions. Car #10 wholly to blame (penalty catalogue V-02).', '§8', 'https://youtu.be/beispiel?t=754', '{}'::uuid[], 'published', '2026-09-17T16:00:00.000Z'),
  (3, 'S2-R02-02', NULL, 10, 21, 16, 'warning', NULL, NULL, NULL, 'Eigene Untersuchung der Stewards: mehrfacher Richtungswechsel auf der Geraden in Runde 11. Keine Kollision, daher Verwarnung.', 'Stewards’ own investigation: more than one change of direction on the straight on lap 11. No contact, therefore a warning.', '§3.2', NULL, '{}'::uuid[], 'published', '2026-09-17T17:00:00.000Z'),
  (4, 'S2-R03-01', 2, 11, 24, 13, 'grid_penalty_next', NULL, 3, NULL, 'ChicaneCharlie hat beim Verteidigen keinen Platz gelassen, obwohl EauRouge_Emil bereits auf Höhe der Vorderachse war. Grid-Strafe von 3 Plätzen für das nächste Rennen.', 'ChicaneCharlie did not leave room while defending although EauRouge_Emil was already alongside the front axle. Three-place grid penalty for the next race.', '§3.3', NULL, '{}'::uuid[], 'published', '2026-09-24T18:00:00.000Z'),
  (5, 'S2-R03-02', NULL, 11, 24, 20, 'position_penalty', NULL, 2, NULL, 'Wiederholter Vorteil durch Verlassen der Strecke in Kurve 4, ohne die Position zurückzugeben.', 'Repeatedly gained an advantage by leaving the track at turn 4 without giving the position back.', '§3.4', NULL, '{}'::uuid[], 'published', '2026-09-24T19:00:00.000Z'),
  (6, 'S2-R04-01', 4, 12, 26, 22, 'time_penalty', 5, NULL, NULL, 'NightRace_Nils ist nach einem Dreher in Kurve 17 ohne ausreichenden Blick auf den nachfolgenden Verkehr zurück auf die Ideallinie gefahren und hat MaxAttackMia zum Ausweichen gezwungen (Strafenkatalog V-04, unsicheres Wiedereinfahren).', 'After spinning at turn 17, NightRace_Nils rejoined the racing line without sufficient regard for following traffic and forced MaxAttackMia to take avoiding action (penalty catalogue V-04, unsafe rejoin).', '§8', NULL, '{"00000000-0000-4000-8000-000000000005"}'::uuid[], 'draft', NULL)
